	),
	JUBBLY_JIVE(
		"Jubbly Jive",
		new WorldArea(2210, 2880, 2488 - 2210, 3072 - 2880, 0),
		VarPlayerID.SAILING_BT_TRIAL_JUBBLY_JIVE_COMPLETED,
		new int[]{1, 2, 3}
	),

