	public static CargoHoldTier fromGameObjectId(int id)
	{
		for (CargoHoldTier tier : values())
		{
			for (int objectId : tier.getGameObjectIds())
			{
				if (objectId == id)
				{
					return tier;
				}
			}
		}

		return null;
	}

	public int getCapacity(SizeClass sizeClass)
	{
		switch (sizeClass)
		{
			case RAFT:
				return capacities[0];
			case SKIFF:
				return capacities[1];
			case SLOOP:
				return capacities[2];
			default:
				log.error("Unknown size class {}", sizeClass);
				return -1;
		}
	}

